func Census(d Decl, workloads []Workload, registry string) (CensusResult, error) {
	res := CensusResult{Total: len(workloads)}
	ours := make([]Workload, 0, len(workloads))
	for _, w := range workloads {
		if bareImage(w.Image, registry) != "" { ours = append(ours, w) }
	}
	res.Examined = len(ours)
	if len(ours) == 0 {
		return res, fmt.Errorf("no cluster workload runs a %s/ image (%d workloads seen) — that is a broken read, not a clean fleet: wrong namespace, lost permissions, or nothing running. Refusing to report a healthy census from an empty measurement", registry, len(workloads))
	}
	res.FleetTag = modalTag(ours)
	if res.FleetTag == "" {
		return res, fmt.Errorf("none of the %d %s/ workloads carries a readable tag — every one is digest-pinned or malformed, so there is no fleet tag to measure staleness against", len(ours), registry)
	}
	res.Findings = append(res.Findings, stragglers(ours, res.FleetTag)...)
	res.Findings = append(res.Findings, declaredNotRunning(d, workloads)...)
	res.Findings = append(res.Findings, runningNotDeclared(d, ours, registry)...)
	return res, nil
}

func stragglers(ours []Workload, fleetTag string) []Violation {
	var out []Violation
	for _, w := range ours {
		if w.Tag == "" || w.Tag == fleetTag { continue }
		switch cmp, ok := compareTags(w.Tag, fleetTag); {
		case !ok:
			out = append(out, Violation{Kind: KindTagUncomparable, Service: w.Name,
				Detail: fmt.Sprintf("%s runs %s at %s while the fleet is on %s, and the two tags cannot be ordered — which is newer is not something this check will guess at", w.Kind, w.Image, w.Tag, fleetTag),
				Remedy: "read the image's provenance stamp (BLD-019) — that is an ancestry question, not a string one."})
		case cmp < 0:
			out = append(out, Violation{Kind: KindStraggler, Service: w.Name,
				Detail: fmt.Sprintf("%s runs %s at %s while the fleet is on %s — nothing about a healthy pod says so, because the pod IS healthy; it is just old", w.Kind, w.Image, w.Tag, fleetTag)})
		default:
			out = append(out, Violation{Kind: KindAheadOfFleet, Service: w.Name,
				Detail: fmt.Sprintf("%s runs %s at %s while the fleet is on %s — nothing but a hand deploy puts a service ahead of the fleet", w.Kind, w.Image, w.Tag, fleetTag),
				Remedy: "the next release MUST NOT reuse this tag — a same-tag re-push serves the node's cached image."})
		}
	}
	return out
}

// numeric, not lexical: this estate has already crossed v1.0.999 -> v1.0.1000,
// where a string comparison says 999 is the newer.
func compareTags(a, b string) (int, bool) {
	pa, oka := parseVersionTag(a); pb, okb := parseVersionTag(b)
	if !oka || !okb || len(pa) != len(pb) { return 0, false }
	for i := range pa {
		if pa[i] != pb[i] { if pa[i] < pb[i] { return -1, true }; return 1, true }
	}
	return 0, true
}

// ROUND 2: the tie-break was `n == bestN && tag > best` — LEXICAL, and the
// gating objection. The fleet tag is the single value every finding is measured
// against, so a wrong tie-break inverts the whole report, not one line.
func modalTag(ours []Workload) string {
	counts := map[string]int{}
	for _, w := range ours { if w.Tag != "" { counts[w.Tag]++ } }
	best, bestN := "", 0
	for tag, n := range counts {
		if n > bestN { best, bestN = tag, n; continue }
		if n != bestN { continue }
		if cmp, ok := compareTags(tag, best); ok {   // NUMERIC, the same helper
			if cmp > 0 { best = tag }
			continue
		}
		if tag > best { best = tag }  // unorderable: stable, not arbitrary
	}
	return best
}

func TestModalTag_TieBreaksNumericallyNotLexically(t *testing.T) {
	tied := []Workload{
		wl("a", "Deployment", registry+"/a", "v1.0.999"),
		wl("b", "Deployment", registry+"/b", "v1.0.999"),
		wl("c", "Deployment", registry+"/c", "v1.0.1000"),
		wl("d", "Deployment", registry+"/d", "v1.0.1000"),
	}
	if got := modalTag(tied); got != "v1.0.1000" {
		t.Fatalf("tie across the 999/1000 boundary picked %q — lexically higher, numerically OLDER; every finding measured against it would be inverted", got)
	}
	// end to end on that fleet: the 999 pair must read BEHIND, never the 1000 pair AHEAD
	res, err := Census(mustDecl(t, goodMakefile+"\nOWN_LINEAGE := a:x b:x c:x d:x\n"), tied, registry)
	if err != nil { t.Fatalf("Census: %v", err) }
	if res.FleetTag != "v1.0.1000" { t.Fatalf("census fleet tag %q on a 999/1000 tie", res.FleetTag) }
	for _, f := range res.Findings {
		if f.Kind == KindStraggler && (f.Service == "c" || f.Service == "d") {
			t.Fatalf("a service on the NEWER side of the tie was reported as behind: %s", f)
		}
		if f.Kind == KindAheadOfFleet && (f.Service == "a" || f.Service == "b") {
			t.Fatalf("a service on the OLDER side of the tie was reported as ahead: %s", f)
		}
	}
	// a clear majority still wins outright — the tie-break must not become the rule
	majority := append(tied, wl("e", "Deployment", registry+"/e", "v1.0.999"))
	if got := modalTag(majority); got != "v1.0.999" { t.Fatalf("a 3-2 majority was overridden by the tie-break: %q", got) }
	// unorderable ties are DETERMINISTIC, or the report is not reproducible
	odd := []Workload{wl("a", "Deployment", registry+"/a", "latest"), wl("b", "Deployment", registry+"/b", "2026-08-22")}
	first := modalTag(odd)
	for i := 0; i < 20; i++ {
		if got := modalTag(odd); got != first { t.Fatalf("unorderable tie is not deterministic: %q then %q", first, got) }
	}
}

func TestCensus_AheadOfFleetIsNotAStraggler(t *testing.T) {
	fleet := append(healthyFleet(), wl("commit-sha-exposure-check", "CronJob", registry+"/commit-sha-exposure-check", "v1.0.1324"))
	// ...declare it in both lists...
	res, err := Census(mustDecl(t, withIt), fleet, registry)
	if err != nil { t.Fatalf("Census: %v", err) }
	if hasKind(res.Findings, KindStraggler, "commit-sha-exposure-check") {
		t.Fatalf("a service AHEAD of the fleet was reported as behind it — the 2026-08-22 false statement, reproduced")
	}
	if !hasKind(res.Findings, KindAheadOfFleet, "commit-sha-exposure-check") {
		t.Fatalf("a hand-deployed service ahead of the fleet was not reported at all: %v", censusKinds(res.Findings))
	}
}

func TestCompareTags(t *testing.T) {
	cases := []struct{ a, b string; want int; ok bool }{
		{"v1.0.999", "v1.0.1000", -1, true},  // lexically WRONG the other way
		{"v1.0.1000", "v1.0.999", 1, true},
		{"v1.0.948", "v1.0.1126", -1, true},  // the real github-runner freeze
		{"latest", "v1.0.1323", 0, false},    // not orderable, and says so
		{"v1.0", "v1.0.1", 0, false},         // different arity: refuse rather than pad
	}
	for _, c := range cases {
		got, ok := compareTags(c.a, c.b)
		if ok != c.ok || (ok && got != c.want) { t.Errorf("compareTags(%q,%q) = (%d,%v), want (%d,%v)", c.a, c.b, got, ok, c.want, c.ok) }
	}
}

func TestCensus_EmptyReadIsAnError(t *testing.T) {
	if _, err := Census(mustDecl(t, goodMakefile), nil, registry); err == nil { t.Fatal("an empty workload list reported clean") }
	notOurs := []Workload{wl("x", "CronJob", "postgres:16-alpine", "16-alpine")}
	if _, err := Census(mustDecl(t, goodMakefile), notOurs, registry); err == nil { t.Fatal("a fleet with none of our images reported clean") }
	digest := []Workload{wl("agent-chassis", "Deployment", registry+"/agent-chassis", "")}
	if _, err := Census(mustDecl(t, goodMakefile), digest, registry); err == nil { t.Fatal("an all-digest fleet reported clean with no fleet tag") }
}

func readWorkloads(ctx context.Context, cs *kubernetes.Clientset, namespace string) ([]releaseset.Workload, error) {
	var out []releaseset.Workload
	deps, err := cs.AppsV1().Deployments(namespace).List(ctx, metav1.ListOptions{})
	if err != nil { return nil, fmt.Errorf("listing deployments in %s: %w", namespace, err) }
	for _, d := range deps.Items {
		for _, c := range d.Spec.Template.Spec.Containers {
			repo, tag := releaseset.SplitImageTag(c.Image)
			out = append(out, releaseset.Workload{Name: d.Name, Kind: "Deployment", Image: repo, Tag: tag})
			break
		}
	}
	crons, err := cs.BatchV1().CronJobs(namespace).List(ctx, metav1.ListOptions{})
	if err != nil { return nil, fmt.Errorf("listing cronjobs in %s: %w", namespace, err) }
	// ...same for CronJobs and DaemonSets; any list error aborts...
	return out, nil
}

func runCensus(root, registry, namespace string) (int, error) {
	decl, err := releaseset.ParseMakefileDecls(mf)
	if err != nil { return exitCannotRun, err }
	cs, via, err := k8sClient()
	if err != nil { return exitCannotRun, err }
	workloads, err := readWorkloads(ctx, cs, namespace)
	if err != nil { return exitCannotRun, err }
	res, err := releaseset.Census(decl, workloads, registry)
	if err != nil { return exitCannotRun, err }
	// the measurement is printed FIRST and ALWAYS — a report that does not say
	// how much it looked at cannot be told from one that looked at nothing
	fmt.Printf("%sRelease census%s — namespace %s, via %s: %d of %d workloads run a %s/ image; the fleet is on %s.\n",
		green, reset, namespace, via, res.Examined, res.Total, registry, res.FleetTag)
	if len(res.Findings) == 0 { return exitOK, nil }
	for _, v := range res.Findings { fmt.Fprintf(os.Stderr, "  %s\n      %s\n", v.String(), v.Remedy) }
	return exitViolation, nil
}

	census = flag.Bool("census", false, "read the CLUSTER instead of the filesystem: report stragglers, declared-but-not-running, and running-but-not-declared")
	ns     = flag.String("namespace", "ai-persona-system", "namespace to census")
)
flag.Parse()

runner := func() (int, error) { return run(*root, *registry, *quiet) }
if *census {
	runner = func() (int, error) { return runCensus(*root, *registry, *ns) }
}
code, err := runner()

.PHONY: release-census
release-census: ## Report cluster-vs-declaration drift (read-only; hand-run, no CronJob)
	@go run ./cmd/releasecheck --census --root . --registry $(REGISTRY) --namespace $(PROJECT_NAME)
